<script setup lang="ts">import{onMounted,ref}from'vue';import{dashboardApi}from'../api/modules';const data=ref<any>(),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{data.value=await dashboardApi.get()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}onMounted(load)</script>
<template><section class="page-head"><div><h2>真实进度，从第一份简历开始</h2><p>这里仅展示当前账户已经完成的业务数据。</p></div></section><div v-if="loading" class="state-card"><el-icon class="spin"><Loading/></el-icon>正在加载工作台</div><div v-else-if="error" class="state-card error">{{error}}<button @click="load">重试</button></div><template v-else><section class="metric-grid-real"><article class="panel"><small>简历版本</small><strong>{{data.resumeCount}}</strong><router-link to="/resumes">管理简历 →</router-link></article><article class="panel"><small>面试场次</small><strong>{{data.interviewCount}}</strong><router-link to="/records">查看记录 →</router-link></article><article class="panel"><small>已生成报告</small><strong>{{data.scoreTrend.length}}</strong><span v-if="data.scoreTrend.length">最近得分 {{Math.round(data.scoreTrend.at(-1))}}</span><span v-else>完成面试后生成</span></article></section><section v-if="!data.resumeCount" class="empty-hero panel"><div><span class="tag orange">第一步</span><h2>上传你的真实简历</h2><p>系统会保存原文件、提取文本并调用已配置模型生成结构化档案。模型未配置时会明确报错。</p><router-link to="/resumes" class="primary-button">上传简历</router-link></div><el-icon><DocumentAdd/></el-icon></section><section v-else class="panel data-list"><div class="panel-title"><h3>最近面试</h3><router-link to="/records">全部记录 →</router-link></div><div v-if="!data.recentInterviews.length" class="empty-inline">还没有面试记录，先生成一套题目吧。</div><div v-for="s in data.recentInterviews" :key="s.id" class="list-row"><span><b>{{s.targetRole}}</b><small>{{s.startedAt}}</small></span><span class="tag" :class="s.status==='COMPLETED'?'green':'orange'">{{s.status}}</span><router-link :to="s.status==='COMPLETED'?`/report/${s.id}`:`/interview/${s.id}`">{{s.status==='COMPLETED'?'查看报告':'继续面试'}}</router-link></div></section></template>
</template>
